    /// <summary>
    /// CoC extension
    /// </summary>
    /// <param name = "_journalName">_journalName</param>
    public void initFromJournalName(JournalNameMap _journalName)
    {
        next initFromJournalName(_journalName);

        LedgerJournalTable  ledgerJournalTable  = this.journalTable();
        LedgerJournalName   ledgerJournalName   = _journalName;

        // MPJ_5366_JournalNameReversalFlag
        ledgerJournalTable.ReverseEntry = ledgerJournalName.METReverseEntry;

    }
